<?php
require_once __DIR__ . '/lib/bootstrap.php';

$currentUser = go_require_login($conn);
$isAdmin = go_is_admin($currentUser);
$panelPath = $isAdmin ? 'admin.php' : 'user.php';
$panelLabel = $isAdmin ? 'Admin panel' : 'User panel';
$pages = ['overview' => 'Overview', 'equipment' => 'Rooms & equipment', 'simulator' => 'Savings simulator', 'actions' => $isAdmin ? 'Alerts & actions' : 'My saving actions', 'reports' => 'Reports'];
if ($isAdmin) {
    $pages['users'] = 'Account management';
    $pages['settings'] = 'Office settings';
}
$pages['profile'] = 'My profile';
$requestedPage = is_string($_GET['page'] ?? null) ? $_GET['page'] : '';
if (!$isAdmin && (($requestedPanel ?? '') === 'admin' || in_array($requestedPage, ['settings', 'users'], true))) {
    show_message('Administrator access required', 'This account can view office energy data and manage its own saving actions.', 'user.php', 403);
}
if (($requestedPanel ?? '') !== ($isAdmin ? 'admin' : 'user')) {
    $query = [];
    if (isset($pages[$requestedPage])) {
        $query['page'] = $requestedPage;
    }
    foreach (['from', 'to'] as $key) {
        if (is_string($_GET[$key] ?? null)) {
            $query[$key] = $_GET[$key];
        }
    }
    foreach ($isAdmin ? ['edit_reading', 'edit_equipment', 'edit_action', 'edit_user'] : ['edit_action'] as $key) {
        if (is_string($_GET[$key] ?? null) && ctype_digit($_GET[$key]) && (float) $_GET[$key] > 0 && (float) $_GET[$key] <= 2147483647) {
            $query[$key] = $_GET[$key];
        }
    }
    header('Location: ' . $panelPath . ($query ? '?' . http_build_query($query) : ''), true, 302);
    exit;
}
$page = isset($pages[$requestedPage]) ? $requestedPage : 'overview';
$data = go_load_data($conn);
$settings = $data['settings'];
$readings = $data['readings'];
$rooms = $data['rooms'];
$equipment = $data['equipment'];
$officeActions = $data['actions'];
$manageableActions = array_values(array_filter($officeActions, static fn($action) => go_can_manage_action($currentUser, $action)));
$actions = $page === 'actions' && !$isAdmin ? $manageableActions : $officeActions;
$from = is_string($_GET['from'] ?? null) ? $_GET['from'] : '';
$to = is_string($_GET['to'] ?? null) ? $_GET['to'] : '';
$filterError = null;
$intervals = go_intervals($readings);
try {
    $summary = go_summary($intervals, $settings, $from, $to);
} catch (InvalidArgumentException $e) {
    $filterError = $e->getMessage();
    $summary = go_summary([], $settings);
}
$today = (new DateTimeImmutable('now', new DateTimeZone('Asia/Kolkata')))->format('Y-m-d');
$alerts = go_alerts($intervals, $settings, $today);
$flash = go_get_flash();
$isDemo = $settings['data_mode'] === 'demo';
$oldAction = go_old_action();
$old = $_SESSION['old'] ?? [];
$openActions = count(array_filter($actions, static fn($action) => $action['status'] === 'open'));
$roomEstimates = [];
$estimatedTotal = 0.0;
foreach ($equipment as $item) {
    $estimate = go_equipment_kwh($item);
    $estimatedTotal += $estimate;
    $roomEstimates[$item['room_id']] = ($roomEstimates[$item['room_id']] ?? 0) + $estimate;
}

function display_number($value, int $places = 1): string
{
    return $value === null ? '—' : number_format((float) $value, $places);
}

function display_date(?string $value): string
{
    return $value && go_date($value) ? go_date($value)->format('d M Y') : '—';
}

function edit_record(array $records, string $column, string $query): array
{
    $value = $_GET[$query] ?? null;
    if (!is_string($value) || !ctype_digit($value)) {
        return [];
    }
    foreach ($records as $record) {
        if ((string) $record[$column] === $value) {
            return $record;
        }
    }
    return [];
}

function office_icon(string $name): string
{
    $paths = [
        'leaf' => '<path d="M20 4c-8-1-15 2-15 8a7 7 0 0 0 7 7c6 0 9-7 8-15Z"/><path d="m4 21 11-11M8 17v-5m0 5h5"/>',
        'overview' => '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
        'equipment' => '<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4M7 8h4"/>',
        'simulator' => '<path d="m13 2-9 12h7l-1 8 10-13h-8l1-7Z"/>',
        'actions' => '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
        'reports' => '<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9Zm0 0v7h7M7 13h10M7 17h6"/>',
        'settings' => '<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',
        'users' => '<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>',
        'profile' => '<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',
        'logout' => '<path d="M9 4H4v16h5m5-12 4 4-4 4m-6-4h10"/>',
        'arrow' => '<path d="M5 12h14m-5-5 5 5-5 5"/>',
        'plus' => '<path d="M12 5v14M5 12h14"/>',
        'download' => '<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
        'check' => '<path d="m5 12 4 4L19 6"/>',
    ];
    return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . ($paths[$name] ?? $paths['leaf']) . '</svg>';
}

$readingForm = $isAdmin ? ($oldAction === 'save_reading' ? $old : edit_record($readings, 'reading_id', 'edit_reading')) : [];
$equipmentForm = $isAdmin ? ($oldAction === 'save_equipment' ? $old : edit_record($equipment, 'equipment_id', 'edit_equipment')) : [];
$actionForm = edit_record($manageableActions, 'action_id', 'edit_action');
if ($page === 'actions' && isset($_GET['edit_action']) && $actionForm === []) {
    show_message('Action unavailable', 'Choose an action that belongs to this account, or return to your action list.', $panelPath . '?page=actions', 404);
}
if ($oldAction === 'save_action') {
    $oldId = $old['action_id'] ?? '';
    if ($oldId === '' || array_filter($manageableActions, static fn($action) => (string) $action['action_id'] === $oldId)) {
        $actionForm = $old;
    }
}
$settingsForm = $oldAction === 'save_settings' ? $old + $settings : $settings;
$chart = ['labels' => [], 'values' => []];
foreach ($summary['intervals'] as $interval) {
    $chart['labels'][] = go_date($interval['start'])->format('d M') . ' – ' . go_date($interval['end'])->format('d M');
    $chart['values'][] = round($interval['daily'], 3);
}
$rangeQuery = http_build_query(['from' => $from, 'to' => $to]);
$periodLabel = $from !== '' || $to !== '' ? (($from !== '' ? display_date($from) : 'First reading') . ' – ' . ($to !== '' ? display_date($to) : 'Latest reading')) : 'All recorded intervals';
$targetPercent = $summary['target_kwh'] > 0 ? $summary['kwh'] / $summary['target_kwh'] * 100 : null;
$scenario = go_scenario(60, 9, 20, 8, 8, $settings['working_days'], $settings['tariff'], $settings['emission_factor']);
go_clear_old();
?>
