 monthly change · kWh (optional)<input id="action-kwh" name="estimated_kwh" type="number" min="-999999999" max="999999999" step="0.001" value="<?= h($actionForm['estimated_kwh'] ?? '') ?>"><small>Positive means reduction; negative means projected increase.</small></label></div><label for="action-notes">Notes & assumptions <span class="optional">optional</span><textarea id="action-notes" name="notes" maxlength="5000" rows="3"><?= h($actionForm['notes'] ?? '') ?></textarea></label></div><div class="form-actions form-grid"><button class="button primary" type="submit">Save action</button><?php if (!empty($actionForm['action_id'])): ?><a class="text-button" href="?page=actions#action-form-panel">Cancel edit</a><?php endif; ?></div></form></section>
